                // any return in unspecified is passed to the afterSwap hook for handling
                int128 hookDeltaSpecified = hookReturn.getSpecifiedDelta();

                // Update the swap amount according to the hook's return, and check that the swap type doesn't change (exact input/output)
                if (hookDeltaSpecified != 0) {
                    bool exactInput = amountToSwap < 0;
                    amountToSwap += hookDeltaSpecified;
                    if (exactInput ? amountToSwap > 0 : amountToSwap < 0) {
                        HookDeltaExceedsSwapAmount.selector.revertWith();
                    }
                }
            }
        }
    }

    /// @notice calls afterSwap hook if permissioned and validates return value
    function afterSwap(
        IHooks self,
        PoolKey memory key,
        IPoolManager.SwapParams memory params,
        BalanceDelta swapDelta,
        bytes calldata hookData,
        BeforeSwapDelta beforeSwapHookReturn
    ) internal returns (BalanceDelta, BalanceDelta) {
        if (msg.sender == address(self)) return (swapDelta, BalanceDeltaLibrary.ZERO_DELTA);

        int128 hookDeltaSpecified = beforeSwapHookReturn.getSpecifiedDelta();
        int128 hookDeltaUnspecified = beforeSwapHookReturn.getUnspecifiedDelta();

        if (self.hasPermission(AFTER_SWAP_FLAG)) {
            hookDeltaUnspecified += self.callHookWithReturnDelta(
                abi.encodeCall(IHooks.afterSwap, (msg.sender, key, params, swapDelta, hookData)),
                self.hasPermission(AFTER_SWAP_RETURNS_DELTA_FLAG)
            ).toInt128();
        }

        BalanceDelta hookDelta;
        if (hookDeltaUnspecified != 0 || hookDeltaSpecified != 0) {
            hookDelta = (params.amountSpecified < 0 == params.zeroForOne)
                ? toBalanceDelta(hookDeltaSpecified, hookDeltaUnspecified)
                : toBalanceDelta(hookDeltaUnspecified, hookDeltaSpecified);

            // the caller has to pay for (or receive) the hook's delta
            swapDelta = swapDelta - hookDelta;
        }
        return (swapDelta, hookDelta);
    }

    /// @notice calls beforeDonate hook if permissioned and validates return value
    function beforeDonate(IHooks self, PoolKey memory key, uint256 amount0, uint256 amount1, bytes calldata hookData)
        internal
        noSelfCall(self)
    {
        if (self.hasPermission(BEFORE_DONATE_FLAG)) {
            self.callHook(abi.encodeCall(IHooks.beforeDonate, (msg.sender, key, amount0, amount1, hookData)));
        }
    }

    /// @notice calls afterDonate hook if permissioned and validates return value
    function afterDonate(IHooks self, PoolKey memory key, uint256 amount0, uint256 amount1, bytes calldata hookData)
        internal
        noSelfCall(self)
    {
        if (self.hasPermission(AFTER_DONATE_FLAG)) {
            self.callHook(abi.encodeCall(IHooks.afterDonate, (msg.sender, key, amount0, amount1, hookData)));
        }
    }

    function hasPermission(IHooks self, uint160 flag) internal pure returns (bool) {
        return uint160(address(self)) & flag != 0;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title AnnouncementRegistry
interface ICreatorAuthority {
    function currentCreatorOf(address token) external view returns (address currentCreator);
}

/// @notice Optional, zero-live-roles creator announcements feed. The factory registers canonical launch tokens,
///         while creator authorization is resolved dynamically so rights transfers require no registry update.
contract AnnouncementRegistry {
    address public immutable factory;

    mapping(address token => bool registered) public isTokenRegistered;
    mapping(address token => mapping(bytes32 announcementId => bool used)) public isAnnouncementIdUsed;

    error NotFactory();
    error NotCreator();
    error AlreadyRegistered();
    error IdAlreadyUsed();
    error ZeroAddress();

    event TokenRegistered(address indexed token);
    event AnnouncementPosted(
        address indexed token,
        address indexed creator,
        bytes32 indexed announcementId,
        string description,
        string announcementURI
    );

    constructor(address factoryAddress) {
        if (factoryAddress == address(0) || factoryAddress.code.length == 0) revert ZeroAddress();
        factory = factoryAddress;
    }

    function registerToken(address token) external {
        if (msg.sender != factory) revert NotFactory();
        if (token == address(0)) revert ZeroAddress();
        if (isTokenRegistered[token]) revert AlreadyRegistered();
        isTokenRegistered[token] = true;
        emit TokenRegistered(token);
    }

    function postAnnouncement(
        address token,
        bytes32 announcementId,
        string calldata description,
        string calldata announcementURI
    ) external {
        if (!isTokenRegistered[token] || msg.sender != ICreatorAuthority(factory).currentCreatorOf(token)) {
            revert NotCreator();
        }
        if (isAnnouncementIdUsed[token][announcementId]) revert IdAlreadyUsed();
        isAnnouncementIdUsed[token][announcementId] = true;
        emit AnnouncementPosted(token, msg.sender, announcementId, description, announcementURI);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {LaunchToken} from "./LaunchToken.sol";

interface ILaunchTokenFactory {
    function tokenDeployer() external view returns (address);
}

/// @title LaunchTokenDeployer
/// @notice One-purpose CREATE2 deployer for ERC20 launch tokens. It keeps token creation bytecode out of the
///         ERC20 launchpad factory while preserving deterministic token addresses and genesis metadata.
contract LaunchTokenDeployer {
    address public immutable factoryInitializer;
    address public factory;

    error AlreadyInitialized();
    error InvalidConfig();
    error TokenAlreadyExists(address token);
    error Unauthorized();

    constructor(address factoryInitializerAddress) {
        if (factoryInitializerAddress == address(0)) revert InvalidConfig();
        factoryInitializer = factoryInitializerAddress;
    }

    function initializeFactory(address factoryAddress) external {
        if (msg.sender != factoryInitializer) revert Unauthorized();
        if (factory != address(0)) revert AlreadyInitialized();
        if (factoryAddress == address(0) || factoryAddress.code.length == 0) revert InvalidConfig();
        if (ILaunchTokenFactory(factoryAddress).tokenDeployer() != address(this)) revert InvalidConfig();
        factory = factoryAddress;
    }

    function predictTokenAddress(bytes32 scopedSalt, LaunchToken.GenesisParams calldata genesisParams)
        external
        view
        returns (address predictedToken)
    {
        return _predictTokenAddress(scopedSalt, genesisParams);
    }

    function tokenBytecodeHash(LaunchToken.GenesisParams calldata genesisParams)
        external
        pure
        returns (bytes32 bytecodeHash)
    {
        return _tokenBytecodeHash(genesisParams);
    }

    function deploy(bytes32 scopedSalt, LaunchToken.GenesisParams calldata genesisParams)
        external
        returns (address token)
    {
        address factoryAddress = factory;
        if (msg.sender != factoryAddress) revert Unauthorized();
        if (genesisParams.factory != factoryAddress) revert InvalidConfig();
        token = _predictTokenAddress(scopedSalt, genesisParams);
        if (token.code.length != 0) revert TokenAlreadyExists(token);
        return address(new LaunchToken{salt: scopedSalt}(genesisParams));
    }

    function _predictTokenAddress(bytes32 scopedSalt, LaunchToken.GenesisParams calldata genesisParams)
        internal
        view
        returns (address predictedToken)
    {
        bytes32 bytecodeHash = _tokenBytecodeHash(genesisParams);
        return
            address(
                uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), scopedSalt, bytecodeHash))))
            );
    }

    function _tokenBytecodeHash(LaunchToken.GenesisParams calldata genesisParams)
        internal
        pure
        returns (bytes32 bytecodeHash)
    {
        return keccak256(abi.encodePacked(type(LaunchToken).creationCode, abi.encode(genesisParams)));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Currency} from "../../src/types/Currency.sol";
import {IERC20Minimal} from "../../src/interfaces/external/IERC20Minimal.sol";
import {IPoolManager} from "../../src/interfaces/IPoolManager.sol";

/// @notice Library used to interact with PoolManager.sol to settle any open deltas.
/// To settle a positive delta (a credit to the user), a user may take or mint.
/// To settle a negative delta (a debt on the user), a user make transfer or burn to pay off a debt.
/// @dev Note that sync() is called before any erc-20 transfer in `settle`.
library CurrencySettler {
    /// @notice Settle (pay) a currency to the PoolManager
    /// @param currency Currency to settle
    /// @param manager IPoolManager to settle to
    /// @param payer Address of the payer, the token sender
    /// @param amount Amount to send
    /// @param burn If true, burn the ERC-6909 token, otherwise ERC20-transfer to the PoolManager
    function settle(Currency currency, IPoolManager manager, address payer, uint256 amount, bool burn) internal {
        // for native currencies or burns, calling sync is not required
        // short circuit for ERC-6909 burns to support ERC-6909-wrapped native tokens
        if (burn) {
            manager.burn(payer, currency.toId(), amount);
        } else if (currency.isAddressZero()) {
            manager.settle{value: amount}();
        } else {
            manager.sync(currency);
            if (payer != address(this)) {
                IERC20Minimal(Currency.unwrap(currency)).transferFrom(payer, address(manager), amount);
            } else {
                IERC20Minimal(Currency.unwrap(currency)).transfer(address(manager), amount);
            }
            manager.settle();
        }
    }

    /// @notice Take (receive) a currency from the PoolManager
    /// @param currency Currency to take
    /// @param manager IPoolManager to take from
    /// @param recipient Address of the recipient, the token receiver
    /// @param amount Amount to receive
    /// @param claims If true, mint the ERC-6909 token, otherwise ERC20-transfer from the PoolManager to recipient
    function take(Currency currency, IPoolManager manager, address recipient, uint256 amount, bool claims) internal {
        claims ? manager.mint(recipient, currency.toId(), amount) : manager.take(currency, recipient, amount);
    }
}

